import math

def is_prime(n):
    """Checks if a number n is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_perfect_cube(n):
    """Checks if n is a perfect cube and returns its cube root k if it is."""
    if n < 0:
        return None

    # Use integer cube root approximation
    # For positive n, we can use round(n**(1/3))
    k_approx = round(n**(1/3))

    if k_approx * k_approx * k_approx == n:
        return k_approx
    return None

# List of primes up to 100
primes = [p for p in range(2, 101) if is_prime(p)]

results = []

for q in primes:
    # Calculate N = q^2 - q + 1
    N = q*q - q + 1

    # Check if N is a perfect cube, N = k^3
    k = is_perfect_cube(N)

    if k is not None:
        # Check if k is prime and k != q
        k_is_prime = is_prime(k)
        k_not_equal_q = (k != q)

        if k_is_prime and k_not_equal_q:
            results.append(f"q={q}: N={N} is a perfect cube ({k}^3). k={k} is prime and k != q. (SUCCESS)")
        else:
            results.append(f"q={q}: N={N} is a perfect cube ({k}^3). k={k} is not prime or k=q. (FAIL)")
    else:
        results.append(f"q={q}: N={N} is not a perfect cube. (SKIP)")

# Print all findings for recording
for result in results:
    print(result)
